namespace ModMon.Cli;

internal static class AgentGuidanceTemplates
{
	public const string OwnershipMarker =
		"<!-- Generated by ModMon. Do not edit this file manually. -->";

	public static string Agents(string projectName)
	{
		return $$"""
{{OwnershipMarker}}
# {{projectName}} Agent Guidance

This repository is a ModMon modular monolith. Preserve these boundaries:

- `{{projectName}}.Api` may reference modules and
  `{{projectName}}.SharedKernel`.
- Modules may reference `{{projectName}}.SharedKernel`, but not other modules.
- `{{projectName}}.SharedKernel` must not reference the API or modules.
- Modules communicate through SharedKernel contracts, not direct database
  access.

Useful commands:

```bash
modmon info
modmon module list
modmon validate --format json
```

Run `modmon validate` after changing projects or project references. Current
validation checks the project-reference graph and required structure; it does
not analyze C# source-level usage.

See `.agent/modmon/` for detailed architecture and workflow guidance.
""";
	}

	public static string Skill(string projectName)
	{
		return $$"""
{{OwnershipMarker}}
# Using ModMon in {{projectName}}

## Workflow

1. Inspect the project with `modmon info`.
2. Add modules with `modmon module add --name <ModuleName>`.
3. Validate after structural changes with `modmon validate`.
4. Use `modmon validate --format json` for automation.

## Boundary Rules

The API can reference modules and SharedKernel. Each module can reference
SharedKernel only. SharedKernel cannot reference application projects. Use
interfaces and events defined in SharedKernel for cross-module communication.

The validator checks declared project references, solution membership, cycles,
and required files. It does not inspect C# symbols, DbContext injection, or
runtime behavior. Boundary or unverifiable-reference failures return exit 5.
""";
	}

	public static string Architecture(string projectName)
	{
		return $$"""
{{OwnershipMarker}}
# {{projectName}} Architecture Patterns

## Project Dependency Matrix

| Source | Allowed project references |
| --- | --- |
| `{{projectName}}.Api` | Modules and `{{projectName}}.SharedKernel` |
| `{{projectName}}.<Module>` | `{{projectName}}.SharedKernel` only |
| `{{projectName}}.SharedKernel` | No API or module projects |

Modules are isolated vertical slices. Each module owns its database context,
entities, services, controllers, and migrations. Cross-module communication
must use contracts or events from SharedKernel rather than another module's
implementation or database context.

`modmon validate` enforces the project graph and fails closed when project
references cannot be resolved. It does not perform compiler-backed source
analysis.
""";
	}

	public static string QuickReference(string projectName)
	{
		return $$"""
{{OwnershipMarker}}
# {{projectName}} ModMon Quick Reference

```bash
modmon info
modmon module list
modmon module add --name Orders
modmon validate
modmon validate --format json
```

Validation returns exit code 0 when structure and project boundaries pass, 4
when no solution can be found, and 5 for structural, boundary, cyclic, or
unverifiable project-reference failures.

Project-specific files:

- `{{projectName}}.sln` — solution
- `{{projectName}}.Api` — application entry point
- `{{projectName}}.SharedKernel` — shared contracts and infrastructure
- `{{projectName}}.<Module>` — isolated business modules
""";
	}
}
